from pwn import *
import sys

binary = '/home/ctfplayer/ctf_files/share/share/chal/unsafe-linking'

# Try sending each menu option and see what prompt/result we get

result = {}
p = process(binary)
def try_option(option):
    p.recvuntil(b'======= CSAW')
    out = b""
    try:
        p.sendline(str(option).encode())
        out = p.recv(timeout=1)
    except Exception as e:
        out = str(e).encode()
    return out

for i in range(1, 5):
    try:
        res = try_option(i)
        result[i] = res.decode(errors='replace')
    except Exception as e:
        result[i] = f'Exception: {e}'
    p.close()
    p = process(binary)

for k, v in result.items():
    print(f'Option {k}:\n{v}\n---\n')

p.close()

