from pwn import *

p = process('/home/ctfplayer/ctf_files/share/chal/unsafe-linking')

def recv_menu():
    res = b''
    while True:
        try:
            cur = p.recv(timeout=0.3)
            res += cur
            if b'Exit' in res:
                break
        except EOFError:
            break
    return res.decode(errors='ignore')

menu = recv_menu()
print(menu)

p.close()

