parsed_args.contents:
from pwn import *
p = process('/home/ctfplayer/ctf_files/share/chal/unsafe-linking')
invalid_indexes = ['-1', '100', '999', 'a', '']
for idx in invalid_indexes:
    for op in ['3','4']:
        try:
            p.sendlineafter('> ',op)
            p.sendlineafter('index:',idx)
            result = p.recv(timeout=1)
            print(f'{op} at idx={idx}: {result}')
        except Exception as e:
            print(f'Exception for {op} idx={idx}: {e}')
p.close()

from pwn import *
p = process('/home/ctfplayer/ctf_files/share/chal/unsafe-linking')
note_max = 16 # guess a possible note limit, will test overflow below
def create(sz, val):
    p.sendlineafter('> ','1')
    p.sendlineafter('size:',str(sz))
    p.sendline(val)

def delete(idx):
    p.sendlineafter('> ','4')
    p.sendlineafter('index:',str(idx))

def read(idx):
    p.sendlineafter('> ','3')
    p.sendlineafter('index:',str(idx))
    try:
        r = p.recv(timeout=0.7)
        return r
    except:
        return b''

# Fill
for i in range(note_max):
    create(0x20,str(i)*4)
print('Filled 16 notes')

# Try 17th note
try:
    create(0x20,'overflow')
    print('Able to create 17th note!')
except Exception as e:
    print('Failed note 17:',e)

# Free all
for i in range(note_max):
    delete(i)

# Try to use freed slots
for i in range(note_max):
    try:
        create(0x20,f'r{i}')
    except Exception as e:
        print(f'Fail reusing slot {i}:',e)

# Try double free on slot 0
try:
    delete(0)
    delete(0)
    print('Double free on slot 0 allowed!')
except Exception as e:
    print('Double free exception:',e)
p.close()

from pwn import *
p = process('/home/ctfplayer/ctf_files/share/chal/unsafe-linking')
def create(sz, val):
    p.sendlineafter('> ','1')
    p.sendlineafter('size:',str(sz))
    p.sendline(val)

create(0x10, 'A'*8)

# Try invalid indexes
for idx in ['-1','100','str']:
    try:
        p.sendlineafter('> ','3')
        p.sendlineafter('index:',idx)
        try:
            print(f'read({idx}):', p.recv(timeout=1))
        except: pass
    except Exception as e:
        print('Read fail', idx, e)

    try:
        p.sendlineafter('> ','4')
        p.sendlineafter('index:',idx)
        try:
            print(f'delete({idx}):', p.recv(timeout=1))
        except: pass
    except Exception as e:
        print('Delete fail', idx, e)

p.close()

